def find_minimal_d(N, K, cities):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return abs(a * b) // gcd(a, b)

    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    def sieve(limit):
        is_prime = [True] * (limit + 1)
        p = 2
        while p * p <= limit:
            if is_prime[p]:
                for i in range(p * p, limit + 1, p):
                    is_prime[i] = False
            p += 1
        primes = []
        for p in range(2, limit + 1):
            if is_prime[p]:
                primes.append(p)
        return primes

    def factorize(n):
        factors = {}
        for prime in primes:
            count = 0
            while n % prime == 0:
                n //= prime
                count += 1
            if count > 0:
                factors[prime] = count
        if n > 1:
            factors[n] = 1
        return factors

    def modular_inverse(a, m):
        m0, x0, x1 = m, 0, 1
        if m == 1:
            return 0
        while a > 1:
            # q is quotient
            q = a // m
            m, a = a % m, m
            x0, x1 = x1 - q * x0, x0
        # Make x1 positive
        if x1 < 0:
            x1 += m0
        return x1

